                    StructField("createdAt", TimestampType()),
                    StructField("updatedAt", TimestampType()),
                    StructField("change", DoubleType()),
                    StructField("comment", StringType()),
                    StructField("action", StringType()),
                    StructField("storageAsset", asset_info),
